e = \"io.insert-koin:koin-compose-viewmodel\", version.ref = \"koinComposeMultiplatform\" }\n\n# Database\nandroidx-room-runtime = { module = \"androidx.room:room-runtime\", version.ref = \"roomRuntime\" }\nandroidx-room-compiler = { module = \"androidx.room:room-compiler\", version.ref = \"roomRuntime\" }\nroom-runtime-android = { module = \"androidx.room:room-runtime-android\", version.ref = \"roomRuntime\" }\nsqlite-bundled = { module = \"androidx.sqlite:sqlite-bundled\", version.ref = \"sqlite\" }\n\n# Firebase\nfirebase = { module = \"com.google.firebase:firebase-bom\", version.ref = \"firebase-android-bom\" }\ncrashlytics = { module = \"com.google.firebase:firebase-crashlytics\" }\ngitlive-firebase-kotlin-crashlytics = { module = \"dev.gitlive:firebase-crashlytics\", version.ref = \"firebase-gitlive-sdk\" }\n\n# Permissions & Location\nmoko-permissions = { module = \"dev.icerock.moko:permissions\", version.ref = \"moko\" }\nmoko-permissions-compose = { module = \"dev.icerock.moko:permissions-compose\", version.ref = \"moko\" }\npermissions-location = { module = \"dev.icerock.moko:permissions-location\", version.ref = \"moko\" }\nplay-services-location = { group = \"com.google.android.gms\", name = \"play-services-location\", version.ref = \"playServicesLocation\" }\n\n[plugins]\n# Android\nandroidApplication = { id = \"com.android.application\", version.ref = \"agp\" }\nandroidLibrary = { id = \"com.android.library\", version.ref = \"agp\" }\n\n# Kotlin\nkotlinMultiplatform = { id = \"org.jetbrains.kotlin.multiplatform\", version.ref = \"kotlin\" }\nkotlin-serialization = { id = \"org.jetbrains.kotlin.plugin.serialization\", version.ref = \"kotlin\" }\n\n# Compose\ncomposeMultiplatform = { id = \"org.jetbrains.compose\", version.ref = \"compose-multiplatform\" }\ncomposeCompiler = { id = \"org.jetbrains.kotlin.plugin.compose\", version.ref = \"kotlin\" }\n\n# Database\nroom = { id = \"androidx.room\", version.ref = \"roomRuntime\" }\nksp = { id = \"com.google.